2: % mean drag from one run file. usage: F = towtank_proc('run_001.csv', 0.02)
3: function F = towtank_proc(fname, sens)
4:     d = readmatrix(fname, 'NumHeaderLines', 3);
5:     t = d(:,1); v = d(:,2);
6:     tare = mean(v(t < 1));
7:     f = (v - tare) / sens;
8:     F = mean(f(t > 3 & t < 8));
9: end

