# independent Re audit using run_log and a different viscosity correlation (IAPWS-ish)
import csv, math
# Vogel from analyze
def mu(T):
    return 2.414e-5*10**(247.8/(T+273.15-140))
def rho(T):
    return 1000*(1-(T+288.9414)/(508929.2*(T+68.12963))*(T-3.9863)**2)
for r in csv.DictReader(open('data/run_log.csv')):
    T=float(r['water_temp_c']); D=float(r['diameter_mm'])/1000; U=float(r['speed_m_s'])
    re=U*D/(mu(T)/rho(T)); re20=U*D/1.0034e-6
    if r['run_id'] in ('1','17','21','30'):
        print(r['run_id'], T, round(re), round(re20), f'{(re/re20-1)*100:+.1f}%')
"
